CREATE TYPE "order_status" AS ENUM ('PENDING','PROCESSING','GIFT_WRAPPED','SHIPPED','DELIVERED','CANCELLED');
CREATE TYPE "order_type" AS ENUM ('SELF','GIFT');
CREATE TABLE "admins" ("id" text PRIMARY KEY,"email" text NOT NULL UNIQUE,"password" text NOT NULL,"name" text NOT NULL,"created_at" timestamp DEFAULT now() NOT NULL,"updated_at" timestamp DEFAULT now() NOT NULL);
CREATE TABLE "categories" ("id" text PRIMARY KEY,"name" text NOT NULL UNIQUE,"slug" text NOT NULL UNIQUE,"description" text,"image_url" text,"icon" text,"is_active" boolean DEFAULT true NOT NULL,"sort_order" integer DEFAULT 0 NOT NULL,"created_at" timestamp DEFAULT now() NOT NULL,"updated_at" timestamp DEFAULT now() NOT NULL);
CREATE TABLE "products" ("id" text PRIMARY KEY,"name" text NOT NULL,"slug" text NOT NULL UNIQUE,"brand" text,"description" text,"sku" text UNIQUE,"cost_price" decimal(10,2) NOT NULL,"sell_price" decimal(10,2) NOT NULL,"discount" decimal(5,2) DEFAULT '0' NOT NULL,"stock" integer DEFAULT 0 NOT NULL,"is_active" boolean DEFAULT true NOT NULL,"is_featured" boolean DEFAULT false NOT NULL,"category_id" text NOT NULL REFERENCES "categories"("id"),"created_at" timestamp DEFAULT now() NOT NULL,"updated_at" timestamp DEFAULT now() NOT NULL);
CREATE TABLE "product_images" ("id" text PRIMARY KEY,"product_id" text NOT NULL REFERENCES "products"("id") ON DELETE CASCADE,"url" text NOT NULL,"alt_text" text,"sort_order" integer DEFAULT 0 NOT NULL,"created_at" timestamp DEFAULT now() NOT NULL);
CREATE TABLE "orders" ("id" text PRIMARY KEY,"order_number" text NOT NULL UNIQUE,"order_type" "order_type" DEFAULT 'GIFT' NOT NULL,"status" "order_status" DEFAULT 'PENDING' NOT NULL,"sender_name" text NOT NULL,"sender_phone" text NOT NULL,"sender_email" text,"recipient_name" text NOT NULL,"recipient_phone" text NOT NULL,"recipient_city" text NOT NULL,"recipient_address" text NOT NULL,"gift_message" text,"gift_wrapping" boolean DEFAULT false NOT NULL,"delivery_charge" decimal(10,2) DEFAULT '0' NOT NULL,"wrapping_charge" decimal(10,2) DEFAULT '0' NOT NULL,"subtotal" decimal(10,2) NOT NULL,"total" decimal(10,2) NOT NULL,"payment_method" text DEFAULT 'COD' NOT NULL,"notes" text,"created_at" timestamp DEFAULT now() NOT NULL,"updated_at" timestamp DEFAULT now() NOT NULL);
CREATE TABLE "order_items" ("id" text PRIMARY KEY,"order_id" text NOT NULL REFERENCES "orders"("id") ON DELETE CASCADE,"product_id" text NOT NULL REFERENCES "products"("id"),"name" text NOT NULL,"price" decimal(10,2) NOT NULL,"cost_price" decimal(10,2) NOT NULL,"quantity" integer NOT NULL,"image_url" text);
CREATE TABLE "store_settings" ("id" text PRIMARY KEY,"key" text NOT NULL UNIQUE,"value" text NOT NULL,"updated_at" timestamp DEFAULT now() NOT NULL);
CREATE TABLE "custom_requests" ("id" text PRIMARY KEY,"name" text NOT NULL,"phone" text NOT NULL,"city" text NOT NULL,"description" text NOT NULL,"budget" text,"occasion" text,"is_gift" boolean DEFAULT false NOT NULL,"recipient_name" text,"status" text DEFAULT 'NEW' NOT NULL,"admin_notes" text,"created_at" timestamp DEFAULT now() NOT NULL,"updated_at" timestamp DEFAULT now() NOT NULL);
CREATE INDEX idx_products_category ON products(category_id);
CREATE INDEX idx_orders_number ON orders(order_number);
CREATE INDEX idx_orders_status ON orders(status);
